    {"id": "drill_b1_th_voiced", "cefr_level": "B1", "category": "TH sonora vs sorda", "title": "TH vibrante: Although / Weather / Smoothly", "ipa": "/ðoʊ/ · /ˈweðər/", "target_phrase": "Although the weather shifted, things ran smoothly.", "example_sentence": "Breathe steadily together every morning.", "spanish_tip": "Pon la lengua entre dientes haciendo vibrar la garganta en 'although'.", "contrast_pair": "think (/θ/) vs though (/ð/)"},

    {"id": "drill_b2_schwa", "cefr_level": "B2", "category": "Vocal Schwa /ə/", "title": "Sílabas átonas con Schwa: Perspective / Analysis", "ipa": "/pərˈspektɪv/", "target_phrase": "From my perspective, analysis beats speed.", "example_sentence": "Support agents documented reliable evidence.", "spanish_tip": "No pronuncies vocales átonas como A/E/O fuertes; relájalas a schwa suave.", "contrast_pair": "stressed vs schwa"},
    {"id": "drill_b2_flap_t", "cefr_level": "B2", "category": "Flap T americana", "title": "T intervocálica suave: Better / Water / Matter", "ipa": "/ˈbet̬ər/ · /ˈmæt̬ər/", "target_phrase": "It matters later whether we test data.", "example_sentence": "Getting better takes steady water breaks.", "spanish_tip": "Entre dos vocales en EE.UU. la T suena como R suave española ('bé-rer').", "contrast_pair": "US /t̬/ vs UK /t/"},
    {"id": "drill_b2_silent_letters", "cefr_level": "B2", "category": "Letras mudas B2", "title": "Muda en contexto: Doubt / Subtle / Debt", "ipa": "/daʊt/ · /det/", "target_phrase": "Doubt vanishes without subtle technical debt.", "example_sentence": "The committee climbed past old constraints.", "spanish_tip": "La B antes de T ('doubt', 'debt', 'subtle') es 100% silenciosa.", "contrast_pair": "doubt -> daut"},

    {"id": "drill_c1_linking_consonant", "cefr_level": "C1", "category": "Linking ejecutivo", "title": "Enlace C+V continuo: Track record / Trade-off", "ipa": "/træk ˈrekərd/", "target_phrase": "Our track record anchors every strategic trade-off.", "example_sentence": "Hold accountable stakeholders in real time.", "spanish_tip": "No separes 'track' y 'record'; enlaza la K directo hacia 'record'.", "contrast_pair": "C + V liaison"},
