    {"id": "drill_c1_rising_falling", "cefr_level": "C1", "category": "Entonación concesiva", "title": "Curva tonal: Albeit / Notwithstanding", "ipa": "/ˌnɑːtwɪθˈstændɪŋ/", "target_phrase": "Notwithstanding upfront friction, retention rose.", "example_sentence": "The launch excelled, albeit cautiously.", "spanish_tip": "Sube ligeramente en la coma tras la concesión para anunciar la tesis principal.", "contrast_pair": "rise-fall contour"},

