    {"id": "drill_c2_cluster_clarity", "cefr_level": "C2", "category": "Clústeres densos C2", "title": "Consonantes complejas: Withstands scrutiny", "ipa": "/wɪðˈstændz ˈskruːtəni/", "target_phrase": "Lucid argument withstands rigorous scrutiny.", "example_sentence": "Epistemic candor bolsters complex accords.", "spanish_tip": "Articula TH->S en 'withstands' sin meter 'e' delante de 'scrutiny'.", "contrast_pair": "withstands scrutiny"},
